INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(14501, 'Psalms 97:11', 'Psalms', 97, 11, '&nbsp;نُور په صادقانو وځلېدلو، او خوشحالى شوه په هغوئ د چا زړونه چې صفا وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14502, 'Psalms 97:12', 'Psalms', 97, 12, '&nbsp;په مالِک خُدائ کښې خوشحالى وکړئ تاسو څوک چې صادقان يئ، او د هغۀ د مقدس نوم ثناء ووايئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14503, 'Psalms 98:1', 'Psalms', 98, 1, '&nbsp;سرود ووايئ مالِک خُدائ ته نوے سرود ووايئ، ځکه چې هغۀ عجيبه او ښکلى کارونه کړى دى، د هغۀ ښى لاس او د هغۀ مقدس مټ د هغۀ دپاره د خلاصون کارونه کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14504, 'Psalms 98:2', 'Psalms', 98, 2, '&nbsp;مالِک خُدائ خپل خلاصون خلقو ته ښودلے دے، او خپل صداقت يې په قومونو څرګند کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14505, 'Psalms 98:3', 'Psalms', 98, 3, '&nbsp;هغۀ خپله مينه او وفادارى چې د بنى اِسرائيلو سره يې کړې وه راپه ياد کړله، زمونږ د خُدائ پاک خلاصون ټولو د زمکې تر آخره پورې وليدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14506, 'Psalms 98:4', 'Psalms', 98, 4, '&nbsp;اے د زمکې ټولو خلقو، مالِک خُدائ ته خوشحالى وکړئ، د خوشحالۍ په آوازونو او ساز سره ورته سندرې ووايئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14507, 'Psalms 98:5', 'Psalms', 98, 5, '&nbsp;مالِک خُدائ ته د رباب ساز وغږوئ، او د رباب د ساز سره ورته سرودونه ووايئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14508, 'Psalms 98:6', 'Psalms', 98, 6, '&nbsp;د بيګل او د ګډورى د ښکر په آوازونو، زمونږ د بادشاه مالِک خُدائ په حضور کښې د خوشحالۍ نعرې ووهئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14509, 'Psalms 98:7', 'Psalms', 98, 7, '&nbsp;سمندر او هر څۀ چې په کښې دى ټول دې چغې او نعرې ووهى، ټوله دُنيا او هر څۀ چې په کښې اوسيږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14510, 'Psalms 98:8', 'Psalms', 98, 8, '&nbsp;سيندونه دې لاسونه وپړقوى، ټول غرونه دې يو ځائ د خوشحالۍ سندرې ووائى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14511, 'Psalms 98:9', 'Psalms', 98, 9, '&nbsp;ټول دې د مالِک خُدائ په حضور کښې سندرې ووائى، ځکه چې هغه د دُنيا عدالت دپاره راځى، هغه به په صداقت سره د دُنيا عدالت وکړى، او د ټولو خلقو به يو شان عدالت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14512, 'Psalms 99:1', 'Psalms', 99, 1, '&nbsp;مالِک خُدائ بادشاه دے، د دُنيا قومونه دې په لړزان شى. هغه چې د وزرو والا مخلوق په مينځ کښې په تخت ناست دے، نو زمکه دې په لړزېدو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14513, 'Psalms 99:2', 'Psalms', 99, 2, '&nbsp;مالِک خُدائ د صيون په ښار کښې عظيم دے، او هغه په ټولو قومونو باندې لوئ او اوچت دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14514, 'Psalms 99:3', 'Psalms', 99, 3, '&nbsp;هغوئ دې ستا د لوئ او هيبتناک نوم ثناء صِفت وکړى، ځکه چې ستا نوم پاک دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14515, 'Psalms 99:4', 'Psalms', 99, 4, '&nbsp;او هغه قادر بادشاه دے څوک چې د اِنصاف او صداقت سره مينه کوى. تا په خپله اِنصاف قائم کړے دے، تا د يعقوب سره هغه کار کړے دے څۀ چې د اِنصاف او صداقت دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14516, 'Psalms 99:5', 'Psalms', 99, 5, '&nbsp;مالِک خُدائ، زمونږ د خُدائ پاک ثناء صِفت وکړئ، او د هغۀ د تخت د وړاندې عبادت وکړئ، ځکه چې هغه مقدس دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14517, 'Psalms 99:6', 'Psalms', 99, 6, '&nbsp;موسىٰ او هارون د هغۀ اِمامان وُو، سموئيل هم د دوئ سره شامل وو چې د مالِک خُدائ نوم به يې يادولو. هغوئ مالِک خُدائ ته سوال وکړو، او هغۀ يې سوال قبول کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14518, 'Psalms 99:7', 'Psalms', 99, 7, '&nbsp;هغۀ دوئ سره د وريځې د ستنې نه خبرې وکړې، هغوئ هغه ټول حُکمونه او قانون منلو کوم چې دوئ ته ورکړے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14519, 'Psalms 99:8', 'Psalms', 99, 8, '&nbsp;اے مالِکه خُدايه زمونږ پاکه خُدايه، د هغوئ سوال تا قبول کړو. تۀ د بنى اِسرائيلو بخښونکے خُدائ پاک يې، کۀ څۀ هم تا د هغوئ بدو عملونو ته سزا ورکړله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14520, 'Psalms 99:9', 'Psalms', 99, 9, '&nbsp;د مالِک خُدائ زمونږ د خُدائ پاک لوئى بيان کړئ، په مقدس غر باندې د هغۀ عبادت وکړئ، ځکه چې مالِک خُدائ زمونږ خُدائ پاک مقدس دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14521, 'Psalms 100:1', 'Psalms', 100, 1, '&nbsp;اے د دُنيا خلقو، د خوشحالۍ نعرې مالِک خُدائ ته ووهئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14522, 'Psalms 100:2', 'Psalms', 100, 2, '&nbsp;او د خوشحالۍ سره د مالِک خُدائ عبادت وکړئ، او د خوشحالۍ په سندرو سره د هغۀ په وړاندې حاضر شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14523, 'Psalms 100:3', 'Psalms', 100, 3, '&nbsp;ځان پوهه کړئ چې هم مالِک خُدائ خُدائ پاک دے، او هم هغۀ مونږ پېدا کړى يُو او مونږ د هغۀ يُو، مونږ د هغۀ خلق او د هغۀ د څرند د ځائ ګډې يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14524, 'Psalms 100:4', 'Psalms', 100, 4, '&nbsp;د هغۀ در ته د شُکر ګزارۍ سره ورننوځئ، او د هغۀ دربار ته د ثناء صِفت کولو سره ورننوځئ، د هغۀ شُکر ګزارى وکړئ او د هغۀ د نوم ثناء صِفت وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14525, 'Psalms 100:5', 'Psalms', 100, 5, '&nbsp;مالِک خُدائ مهربانه دے او د هغۀ مينه د تل دپاره وى، او د هغۀ وفادارى به تر نسلونو پورې جارى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14526, 'Psalms 101:1', 'Psalms', 101, 1, '&nbsp;زۀ به ستا د مينې او اِنصاف سرود ووايم، او زۀ به تا ته مالِک خُدايه د ثناء سرود ووايم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14527, 'Psalms 101:2', 'Psalms', 101, 2, '&nbsp;زۀ به احتياط کوم چې بې‌داغه ژوند تېر کړم، خو تۀ به زما د مدد دپاره کله راځې؟ او زۀ به په خپل کور کښې په صفا زړۀ ژوند تېروم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14528, 'Psalms 101:3', 'Psalms', 101, 3, '&nbsp;کوم څيزونه چې فاسد وى زۀ به ورته نۀ ګورم. د بې‌ايمانانو د کارونو نه به نفرت کوم، او زۀ به د هغوئ سره کار نۀ ساتم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14529, 'Psalms 101:4', 'Psalms', 101, 4, '&nbsp;او د چا چې وى زړونه کاږۀ ما نه به لرې وى، او زۀ به د بدۍ سره هيڅ کار نۀ ساتم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14530, 'Psalms 101:5', 'Psalms', 101, 5, '&nbsp;څوک چې پټ کوى د خپلو ګاونډيانو غېبتونه، زۀ به هغه چپ کوم. د چا چې سترګې کبرژنې او مغروره وى، هغه سړے به زۀ نۀ برداشت کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14531, 'Psalms 101:6', 'Psalms', 101, 6, '&nbsp;زما سترګې به په دُنيا کښې د ايماندارو په لټون شى، چې هغوئ ما سره اوسيږى. د چا کردار چې بې‌داغه وى نو هغوئ به زما خِدمت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14532, 'Psalms 101:7', 'Psalms', 101, 7, '&nbsp;زما په کور کښې به دوکه مار ته د اوسېدو اجازت نۀ وى، او دروغژن به زما په حضور کښې ودرېدلے نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14533, 'Psalms 101:8', 'Psalms', 101, 8, '&nbsp;هر سحر به زۀ هغه بدکاره چې په مُلک کښې مې اوسيږى تباه کوم، زۀ به هر بدعمله د مالِک خُدائ د ښار نه ورک کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14534, 'Psalms 102:1', 'Psalms', 102, 1, '&nbsp;اے مالِکه خُدايه، سوال قبول کړه زما، تا ته دې سوال زارى درورسيږى زما.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14535, 'Psalms 102:2', 'Psalms', 102, 2, '&nbsp;خپل مخ دې رانه مۀ اړوه کله چې په سخته کښې يم. ما ته غوږ شه کله چې تا نه سوال وکړم او زر مې قبلوه سوالونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14536, 'Psalms 102:3', 'Psalms', 102, 3, '&nbsp;زما ژوند د لوګى په شان فنا کيږى، زما هډُوکى لکه د سکروټو په شان بليږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14537, 'Psalms 102:4', 'Psalms', 102, 4, '&nbsp;زړۀ مې بيمار او د واښو په شانې اوچ شو، ما نه خپله روټۍ خوړل هېر شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14538, 'Psalms 102:5', 'Psalms', 102, 5, '&nbsp;زما په زوره زبيرګو په وجه، تش هډُوکى او تشه څرمن پاتې شوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14539, 'Psalms 102:6', 'Psalms', 102, 6, '&nbsp;د صحرا د ګونګى په شان يم، زۀ لکه د ګونګى چې په تباه شوو کنډرو کښې اوسېږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14540, 'Psalms 102:7', 'Psalms', 102, 7, '&nbsp;ويښ پروت يم او زۀ د هغه مارغۀ په شان شوم، چې ځان له پاس په چت باندې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14541, 'Psalms 102:8', 'Psalms', 102, 8, '&nbsp;ټوله ورځ دشمنان ما ته پېغور راکوى، هغوئ ما دومره سپکوى چې په لعنت وئيلو کښې زما نوم استعمالوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14542, 'Psalms 102:9', 'Psalms', 102, 9, '&nbsp;ځکه د روټۍ په ځائ ايرې زما خوراک شولې، او د اوبو سره مې خپلې اوښکې څښلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14543, 'Psalms 102:10', 'Psalms', 102, 10, '&nbsp;ستا د قهر او لوئ غضب په وجه، نو زۀ دې اوچت کړمه او يو خوا ته دې وغورزولم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14544, 'Psalms 102:11', 'Psalms', 102, 11, '&nbsp;زما عمر لکه د مازيګر د سورى په شان تير شو، لکه د واښو په شان اوچ شوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14545, 'Psalms 102:12', 'Psalms', 102, 12, '&nbsp;خو تۀ، اے مالِکه خُدايه، تر ابده به په تخت ناست يې، ستا د نوم پېژندګلو به تر نسلونو پورې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14546, 'Psalms 102:13', 'Psalms', 102, 13, '&nbsp;تۀ به راپاڅې او په صيون ښار به رحم وکړې، او هغه وخت رارسېدلے دے چې خپل احسان دې ورته ښکاره کړې، او مقرر شوے وخت رارسېدلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14547, 'Psalms 102:14', 'Psalms', 102, 14, '&nbsp;د هغې کاڼى ستا په خِدمتګارانو ګران دى، او د هغې په يوې ذرې خاورې هم رحم کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14548, 'Psalms 102:15', 'Psalms', 102, 15, '&nbsp;قومونه به د مالِک خُدائ د نوم نه يريږى، او د دُنيا ټول بادشاهان به ستا د جلال او عظمت نه يريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14549, 'Psalms 102:16', 'Psalms', 102, 16, '&nbsp;خو مالِک خُدائ به دوباره د صيون ښار آباد کړى، او بيا به په خپل جلال کښې ځان څرګند کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14550, 'Psalms 102:17', 'Psalms', 102, 17, '&nbsp;هغه به د مسکينانو دُعا قبوله کړى، او هغه به د دوئ سوال ته سپک نظر نۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14551, 'Psalms 102:18', 'Psalms', 102, 18, '&nbsp;د راتلونکو نسلونو دپاره دې دا وليکلے شى، کوم خلق چې لا پېدا شوى نۀ دى د مالِک خُدائ ثناء دې ووائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14552, 'Psalms 102:19', 'Psalms', 102, 19, '&nbsp;مالِک خُدائ د خپل بره مقدس مقام نه لاندې وکتل، بره آسمان نه هغۀ زمکې ته نظر وکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14553, 'Psalms 102:20', 'Psalms', 102, 20, '&nbsp;چې د قېديانو زبيرګى واورى، په چا چې حُکم د مرګ شوے دے هغوئ د مرګ نه آزاد کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14554, 'Psalms 102:21', 'Psalms', 102, 21, '&nbsp;نو د مالِک خُدائ د نوم به په صيون کښې اعلان وشى، او په يروشلم کښې به د هغۀ ثناء صِفت وشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14555, 'Psalms 102:22', 'Psalms', 102, 22, '&nbsp;کله چې قومونه او بادشاهتونه راجمع شى، او د مالِک خُدائ عبادت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14556, 'Psalms 102:23', 'Psalms', 102, 23, '&nbsp;زما طاقت يې په نيمه لار کښې ختم کړو، او هغۀ زما ژوند لنډ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14557, 'Psalms 102:24', 'Psalms', 102, 24, '&nbsp;نو ما ووئيل، ”زما پاکه خُدايه، زما ژوند زما نه په ځوانۍ کښې مۀ اخله، تۀ خو به همېشه همېشه پورې ژوندے يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14558, 'Psalms 102:25', 'Psalms', 102, 25, '&nbsp;په شروع کښې تا د زمکې بنيادونه کېښودل، آسمانونه ستا د لاس کارونه دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14559, 'Psalms 102:26', 'Psalms', 102, 26, '&nbsp;دا هر څۀ به ټول ختم شى خو تۀ به قائم پاتې شې، دا هر څۀ به لکه د جامو په شان زاړۀ شى، تۀ به يې لکه د جامو په شان بدلې کړې، او دا هر څۀ به فنا شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14560, 'Psalms 102:27', 'Psalms', 102, 27, '&nbsp;خو بس تۀ به په يو حال پاتې شې، او ستا کالونه به هيڅکله ختم نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14561, 'Psalms 102:28', 'Psalms', 102, 28, '&nbsp;ستا د خِدمتګارو بچى به ستا په حضور کښې اوسيږى، او د هغوئ اولاد به ستا په حضور کښې قائم دائم وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14562, 'Psalms 103:1', 'Psalms', 103, 1, '&nbsp;اے زما روحه، د مالِک خُدائ ثناء ووايه، اے زما ټول ځانه، د مالِک خُدائ د مقدس نوم ثناء ووايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14563, 'Psalms 103:2', 'Psalms', 103, 2, '&nbsp;اے زما روحه، د مالِک خُدائ ثناء ووايه، چې د هغۀ ټول احسانونه هېر نۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14564, 'Psalms 103:3', 'Psalms', 103, 3, '&nbsp;څوک چې ستا ټول ګناهونه معاف کوى، او چې ستا ټول مرضونه جوړوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14565, 'Psalms 103:4', 'Psalms', 103, 4, '&nbsp;څوک چې ستا ژوند د مرګ نه په بيعه اخلى، او خپل د مينې او رحم تاج ستا په سر ږدى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14566, 'Psalms 103:5', 'Psalms', 103, 5, '&nbsp;او څوک چې په ښۀ څيزونو ستا ارمانونه پوره کوى، نو چې د باز په شان ستا ځوانى تازه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14567, 'Psalms 103:6', 'Psalms', 103, 6, '&nbsp;مالِک خُدائ خپل صداقت سر ته رسوى، او د ټولو مظلومانو سره اِنصاف کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14568, 'Psalms 103:7', 'Psalms', 103, 7, '&nbsp;هغۀ موسىٰ ته خپلې طريقې وښودلې، خپل اعمال يې بنى اِسرائيلو ته ‎ښکاره کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14569, 'Psalms 103:8', 'Psalms', 103, 8, '&nbsp;مالِک خُدائ رحيم او مهربان دے، زر نۀ په غصه کيږى او د هغۀ مينه پائيداره ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14570, 'Psalms 103:9', 'Psalms', 103, 9, '&nbsp;هغه به هر وخت نۀ ملامتوى، او خپل قهر به تر ابده نۀ ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14571, 'Psalms 103:10', 'Psalms', 103, 10, '&nbsp;هغه مونږ ته زمونږ د ګناهونو په اندازه سزا نۀ راکوى، او نۀ زمونږ د ګناهونو په مطابق بدله راکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14572, 'Psalms 103:11', 'Psalms', 103, 11, '&nbsp;نو لکه څنګه چې آسمانونه د زمکې نه اوچت دى، نو دومره د دۀ مينه د هغوئ دپاره لويه ده څوک چې د هغۀ نه يريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14573, 'Psalms 103:12', 'Psalms', 103, 12, '&nbsp;څومره چې مشرق د مغرب نه لرې دے، نو دومره هغۀ زمونږ قصورونه مونږ نه لرى کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14574, 'Psalms 103:13', 'Psalms', 103, 13, '&nbsp;څومره چې پلار په خپلو بچو باندې مهربان وى، نو دومره مالِک خُدائ په هغوئ مهربانه دے څوک چې د هغۀ نه يريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14575, 'Psalms 103:14', 'Psalms', 103, 14, '&nbsp;ځکه چې هغۀ ته پته ده چې مونږ څنګه جوړ شوى يُو، هغۀ ته دا ياد دى چې مونږ خاورې يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14576, 'Psalms 103:15', 'Psalms', 103, 15, '&nbsp;د انسان ژوند د واښو په شان دے، لکه د مېدان د ګل په شان غوړيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14577, 'Psalms 103:16', 'Psalms', 103, 16, '&nbsp;کله چې هوا ورباندې ولګيږى نو ختم شى، او بيا په هغې ځائ کښې نۀ ښکارى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14578, 'Psalms 103:17', 'Psalms', 103, 17, '&nbsp;تر ابده ابده د مالِک خُدائ مينه د هغوئ سره وى څوک چې د هغۀ نه يريږى، او د هغۀ صداقت د هغوئ د نسلونو سره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14579, 'Psalms 103:18', 'Psalms', 103, 18, '&nbsp;او د هغوئ سره څوک چې د هغۀ د لوظ پابند وى، او د هغوئ سره څوک چې د هغۀ په حُکمونو عمل کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14580, 'Psalms 103:19', 'Psalms', 103, 19, '&nbsp;مالِک خُدائ خپل تخت په آسمان کښې قائم کړے دے، او د هغۀ بادشاهى په هر څۀ باندې قائمه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14581, 'Psalms 103:20', 'Psalms', 103, 20, '&nbsp;فرښتو د مالِک خُدائ ثناء صِفت ادا کړئ، تاسو چې زورَورې يئ او د هغۀ په حُکمونو عمل کوئ، او د هغۀ د کلام تابعدارى کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14582, 'Psalms 103:21', 'Psalms', 103, 21, '&nbsp;اے د فرښتو لښکرو، تاسو د مالِک خُدائ ثناء ووايئ، اے د هغۀ خِدمتګارانو چې د هغۀ رضا پوره کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14583, 'Psalms 103:22', 'Psalms', 103, 22, '&nbsp;اے د مالِک خُدائ ټولو مخلوقاتو د هغۀ د بادشاهۍ په هر ځائ کښې د هغۀ ثناء صِفت وکړئ. اے زما روحه د مالِک خُدائ ثناء صِفت وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14584, 'Psalms 104:1', 'Psalms', 104, 1, '&nbsp;اے زما روحه، د مالِک خُدائ ثناء صِفت وکړه. اے مالِکه خُدايه، تۀ ډېر لوئ يې زما پاکه خُدايه، تا د شان او شوکت او لويئ جامې اچولې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14585, 'Psalms 104:2', 'Psalms', 104, 2, '&nbsp;هغۀ خپل ځان نه نُور لکه د جامو راتاو کړے دے، هغۀ آسمانونه لکه د پړدې په شان غوړولې دى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14586, 'Psalms 104:3', 'Psalms', 104, 3, '&nbsp;هغه د خپل پاس کور تيرونه د اوبو دپاسه ږدى. هغه د وريځو نه جنګى ګاډۍ جوړوى او د هوا په وزرو سوريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14587, 'Psalms 104:4', 'Psalms', 104, 4, '&nbsp;هوا د هغۀ پېغام رسوونکى جوړيږى، او د اور لمبې د هغۀ خِدمتګارې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14588, 'Psalms 104:5', 'Psalms', 104, 5, '&nbsp;هغه زمکه په خپلو بنيادونو باندې مضبوطوى، چې هيڅکله به نۀ خوځيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14589, 'Psalms 104:6', 'Psalms', 104, 6, '&nbsp;تا زمکه په سېلاب باندې لکه د جامو پټه کړې ده، او اوبۀ د غرونو دپاسه ودرېدلې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14590, 'Psalms 104:7', 'Psalms', 104, 7, '&nbsp;ستا په رټنه اوبۀ وتښتېدلې، ستا د آواز په تندر سره وتښتېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14591, 'Psalms 104:8', 'Psalms', 104, 8, '&nbsp;د غرونو نه ښکته وبهېدلې، او لاندې درو ته لاړلې، او هغه ځايونو ته چې کوم تا ورته مقرر کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14592, 'Psalms 104:9', 'Psalms', 104, 9, '&nbsp;تا ورته حد مقرر کړو د هغې نه وړاندې نۀ ځى، هيڅکله به بيا زمکه پټه نۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14593, 'Psalms 104:10', 'Psalms', 104, 10, '&nbsp;تۀ په درو کښې د چينو نه اوبۀ راوباسې، چې د غرونو په مينځ کښې بهيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14594, 'Psalms 104:11', 'Psalms', 104, 11, '&nbsp;او د بيابان ټول ځناور ترې نه اوبۀ څښى، او ځنګلى خرونه ورباندې خپله تنده ماتوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14595, 'Psalms 104:12', 'Psalms', 104, 12, '&nbsp;مارغان د روانو اوبو په خوا کښې جالې جوړوى، او د څانګو په مينځ کښې سندرې وائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14596, 'Psalms 104:13', 'Psalms', 104, 13, '&nbsp;او تۀ د خپل آسمانى کور نه غرونه اوبۀ کوې، او ستا د کارونو د مېوو په وجه زمکه معموريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14597, 'Psalms 104:14', 'Psalms', 104, 14, '&nbsp;تۀ د څاروو دپاره ګياه شنه کوې، او تۀ د بنيادمو دپاره شنۀ بوټى راټوکوې، او د زمکې نه خوراک پېدا کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14598, 'Psalms 104:15', 'Psalms', 104, 15, '&nbsp;تۀ د بنيادم د خوشحالولو دپاره مے پېدا کوې، او تۀ تېل د هغۀ د مخ د تازه والى دپاره پېدا کوې، او تۀ روټۍ پېدا کوې کومه چې انسان ته طاقت ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14599, 'Psalms 104:16', 'Psalms', 104, 16, '&nbsp;د مالِک خُدائ ونې ښې سيرابه شوې، د لبنان دِيار کوم چې هغۀ کَرلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14600, 'Psalms 104:17', 'Psalms', 104, 17, '&nbsp;هلته مارغان په کښې ځان له جالې جوړوى، او ډينګان د چلغوزو ونو کښې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');